-- Importación actualizada Grupo Tejeda - SQL Server 2025 / MonsterASP.NET
-- Fuente: LTKResultadoBrutoDetalladoApi (2) (2) (1).xlsx
-- Agencias activas: 3122 | Grupos activos: 161
-- La carga conserva auditorías históricas y desactiva agencias que ya no aparecen en el archivo.

SET NOCOUNT ON;
SET XACT_ABORT ON;

IF OBJECT_ID(N'dbo.agencies',N'U') IS NULL THROW 50001,N'Falta dbo.agencies. Ejecuta primero 01_EJECUTAR_EN_SQL_SERVER.sql.',1;
IF COL_LENGTH(N'dbo.agencies',N'id') IS NULL OR COL_LENGTH(N'dbo.agencies',N'codigo') IS NULL OR COL_LENGTH(N'dbo.agencies',N'terminal') IS NULL OR COL_LENGTH(N'dbo.agencies',N'grupo') IS NULL
    THROW 50002,N'La tabla dbo.agencies no tiene las columnas básicas. Ejecuta primero 01_EJECUTAR_EN_SQL_SERVER.sql.',1;

-- DDL dinámico: evita el error 'Invalid column name' al actualizar una base creada con una versión anterior.
IF COL_LENGTH(N'dbo.agencies',N'source_key') IS NULL
BEGIN
    EXEC sys.sp_executesql N'ALTER TABLE dbo.agencies ADD source_key nvarchar(200) NULL;';
    EXEC sys.sp_executesql N'UPDATE dbo.agencies SET source_key=CONCAT(N''LEGACY:'',id) WHERE source_key IS NULL; ALTER TABLE dbo.agencies ALTER COLUMN source_key nvarchar(200) NOT NULL;';
END;
IF COL_LENGTH(N'dbo.agencies',N'region') IS NULL EXEC sys.sp_executesql N'ALTER TABLE dbo.agencies ADD region nvarchar(120) NULL;';
IF COL_LENGTH(N'dbo.agencies',N'is_active') IS NULL EXEC sys.sp_executesql N'ALTER TABLE dbo.agencies ADD is_active bit NOT NULL CONSTRAINT DF_agencies_active_import DEFAULT(1) WITH VALUES;';
IF COL_LENGTH(N'dbo.agencies',N'operational_status') IS NULL EXEC sys.sp_executesql N'ALTER TABLE dbo.agencies ADD operational_status varchar(20) NOT NULL CONSTRAINT DF_agencies_operational_status_import DEFAULT(''ACTIVE'') WITH VALUES;';
IF COL_LENGTH(N'dbo.agencies',N'status') IS NULL EXEC sys.sp_executesql N'ALTER TABLE dbo.agencies ADD status varchar(30) NOT NULL CONSTRAINT DF_agencies_status_import DEFAULT(''PENDING'') WITH VALUES;';
IF COL_LENGTH(N'dbo.agencies',N'updated_at') IS NULL EXEC sys.sp_executesql N'ALTER TABLE dbo.agencies ADD updated_at datetime2(3) NOT NULL CONSTRAINT DF_agencies_updated_import DEFAULT(SYSUTCDATETIME()) WITH VALUES;';

BEGIN TRANSACTION;
CREATE TABLE #LTKImport(source_key nvarchar(200) NOT NULL PRIMARY KEY,codigo nvarchar(100) NOT NULL,terminal nvarchar(300) NOT NULL,grupo nvarchar(150) NOT NULL,region nvarchar(120) NOT NULL);








-- El DML también se compila de forma diferida para reconocer las columnas agregadas arriba.
EXEC sys.sp_executesql N'
UPDATE dbo.agencies SET is_active=0,updated_at=SYSUTCDATETIME() WHERE source_key LIKE N''LTK:%'';

MERGE dbo.agencies WITH(HOLDLOCK) AS target
USING #LTKImport AS source ON target.source_key=source.source_key
WHEN MATCHED THEN UPDATE SET codigo=source.codigo,terminal=source.terminal,grupo=source.grupo,region=source.region,operational_status=''ACTIVE'',is_active=1,updated_at=SYSUTCDATETIME()
WHEN NOT MATCHED THEN INSERT(id,source_key,codigo,terminal,grupo,region,status,is_active,operational_status)
VALUES(CONVERT(char(36),NEWID()),source.source_key,source.codigo,source.terminal,source.grupo,source.region,''PENDING'',1,''ACTIVE'');
';

DROP TABLE #LTKImport;
COMMIT TRANSACTION;

EXEC sys.sp_executesql N'
SELECT CASE WHEN COUNT(*)=3122 AND COUNT(DISTINCT grupo)=161 THEN N''OK'' ELSE N''REVISAR'' END AS validacion,COUNT(*) AS agencias_activas,COUNT(DISTINCT grupo) AS grupos_activos FROM dbo.agencies WHERE is_active=1 AND source_key LIKE N''LTK:%'';
SELECT region,COUNT(*) AS agencias,COUNT(DISTINCT grupo) AS grupos FROM dbo.agencies WHERE is_active=1 AND source_key LIKE N''LTK:%'' GROUP BY region ORDER BY region;
';
